INSERT INTO deck_slides (deck, position, template, content) VALUES
  ('tenant', 1, 'cover', $j${"mark": {"en": "Balkina AI · For Your Business", "sr": "Balkina AI · Za vaš biznis"}, "title": {"en": "Automate your booking & fill up your calendar", "sr": "Automatizujte zakazivanje i popunite svoj kalendar"}, "lede": {"en": "with Balkina — an AI booking platform where new customers find you, regulars rebook more often, and your schedule takes care of itself.", "sr": "uz Balkinu — AI platformu za zakazivanje na kojoj vas novi klijenti pronalaze, stalni se vraćaju češće, a raspored se vodi sam."}}$j$::jsonb),
  ('tenant', 2, 'types', $j${"eyebrow": {"en": "Built For", "sr": "Napravljeno za"}, "items": [{"label": {"en": "Salons", "sr": "Salone"}}, {"label": {"en": "Barbershops", "sr": "Berbernice"}}, {"label": {"en": "Spas", "sr": "Spa centre"}}, {"label": {"en": "Trainers", "sr": "Trenere"}}, {"label": {"en": "Clinics", "sr": "Ordinacije"}}, {"label": {"en": "Dentists", "sr": "Stomatologe"}}, {"label": {"en": "Physiotherapists", "sr": "Fizioterapeute"}}, {"label": {"en": "Nail studios", "sr": "Nail studije"}}, {"label": {"en": "Massage", "sr": "Masaže"}}, {"label": {"en": "Yoga studios", "sr": "Joga studije"}}, {"label": {"en": "Gyms", "sr": "Teretane"}}, {"label": {"en": "Restaurants", "sr": "Restorane"}}, {"label": {"en": "Cafés", "sr": "Kafiće"}}, {"label": {"en": "Tour operators", "sr": "Turističke agencije"}}, {"label": {"en": "Experiences", "sr": "Doživljaje"}}]}$j$::jsonb),
  ('tenant', 3, 'problem', $j${"eyebrow": {"en": "The Problem", "sr": "Problem"}, "title": {"en": "Bookings you never even saw are going to someone else", "sr": "Rezervacije koje niste ni videli odlaze nekom drugom"}, "gaps": [{"heading": {"en": "Hard to discover", "sr": "Teško vas je pronaći"}, "text": {"en": "New customers can't find you — discovery today is word of mouth and whoever shows up first on Google", "sr": "Novi klijenti ne znaju za vas — otkrivanje se danas svodi na preporuke i na to ko prvi iskoči na Google-u"}}, {"heading": {"en": "Slow to book", "sr": "Sporo zakazivanje"}, "text": {"en": "Booking happens over calls, DMs and email back-and-forth — hours to close what should take seconds", "sr": "Rezervacije idu preko poziva, poruka i mejlova — satima se zatvara ono što traje sekunde"}}, {"heading": {"en": "Missed demand", "sr": "Propuštena tražnja"}, "text": {"en": "Calls while your hands are busy and messages at midnight go unanswered — those bookings go elsewhere", "sr": "Pozivi dok su vam ruke zauzete i poruke u ponoć ostaju bez odgovora — te rezervacije odu drugom"}}, {"heading": {"en": "Forgotten regulars", "sr": "Zaboravljeni stalni klijenti"}, "text": {"en": "Your best customers drift — not because they left, but because nobody reminded them they're due", "sr": "Najbolji klijenti se osipaju — ne zato što su otišli, već zato što ih niko nije podsetio da je vreme"}}]}$j$::jsonb),
  ('tenant', 4, 'overview', $j${"eyebrow": {"en": "The Platform", "sr": "Platforma"}, "title": {"en": "Run your business end to end with one tool", "sr": "Vodite svoj biznis od početka do kraja uz jedan alat"}, "lede": {"en": "Every module below is included. The next slides go through each one.", "sr": "Svaki modul ispod je uključen. Naredni slajdovi prolaze kroz svaki od njih."}, "features": [{"name": {"en": "AI receptionist", "sr": "AI recepcioner"}, "desc": {"en": "books for you 24/7 in chat — instant or with your approval", "sr": "zakazuje umesto vas 24/7 u chatu — odmah ili uz vaše odobrenje"}}, {"name": {"en": "Discovery in the app", "sr": "Otkrivanje u aplikaciji"}, "desc": {"en": "nearby customers find you with open slots", "sr": "klijenti u blizini vas pronalaze sa slobodnim terminima"}}, {"name": {"en": "Your booking link", "sr": "Vaš link za rezervacije"}, "desc": {"en": "Instagram, Google, WhatsApp — one link, direct bookings", "sr": "Instagram, Google, WhatsApp — jedan link, direktne rezervacije"}}, {"name": {"en": "Smart rebooking", "sr": "Pametno ponovno zakazivanje"}, "desc": {"en": "AI nudges regulars when they're due", "sr": "AI podseća stalne klijente kada im je vreme"}}, {"name": {"en": "Reminders", "sr": "Podsetnici"}, "desc": {"en": "AI and SMS reminders cut no-shows", "sr": "AI i SMS podsetnici smanjuju nedolaske"}}, {"name": {"en": "Customer CRM", "sr": "CRM klijenata"}, "desc": {"en": "history and preferences in one profile", "sr": "istorija i navike u jednom profilu"}}, {"name": {"en": "Services, staff & schedules", "sr": "Usluge, osoblje i rasporedi"}, "desc": {"en": "durations, buffers, days off, locations", "sr": "trajanja, pauze, slobodni dani, lokacije"}}, {"name": {"en": "Appointments", "sr": "Termini"}, "desc": {"en": "approve, reschedule, reach customers in one tap", "sr": "odobrite, pomerite, kontaktirajte klijente jednim dodirom"}}, {"name": {"en": "Coupons & packages", "sr": "Kuponi i paketi"}, "desc": {"en": "entice new customers, upsell regulars", "sr": "privucite nove, prodajte više stalnima"}}, {"name": {"en": "Calendar sync", "sr": "Sinhronizacija kalendara"}, "desc": {"en": "Google two-way, iCal, Airbnb, Calendly", "sr": "Google dvosmerno, iCal, Airbnb, Calendly"}}, {"name": {"en": "Travel platforms", "sr": "Turističke platforme"}, "desc": {"en": "Bokun: Viator, GetYourGuide, Airbnb Experiences", "sr": "Bokun: Viator, GetYourGuide, Airbnb Experiences"}}, {"name": {"en": "Restaurants & events", "sr": "Restorani i događaji"}, "desc": {"en": "tables and ticketed evenings, same dashboard", "sr": "stolovi i večeri s ulaznicama, ista tabla"}}]}$j$::jsonb),
  ('tenant', 5, 'points-chat', $j${"eyebrow": {"en": "AI Receptionist", "sr": "AI recepcioner"}, "title": {"en": "Balkina AI receptionist that never sleeps", "sr": "Balkina AI recepcioner koji nikad ne spava"}, "points": [{"strong": {"en": "New customers will easily discover your business:", "sr": "Novi klijenti će lako otkriti vaš biznis:"}, "text": {"en": "find real-time availability and book your services — day or night", "sr": "vide dostupnost u realnom vremenu i zakazuju vaše usluge — danju i noću"}}, {"strong": {"en": "Instant confirmation or your approval:", "sr": "Trenutna potvrda ili vaše odobrenje:"}, "text": {"en": "you decide which bookings need a yes from you", "sr": "vi odlučujete koje rezervacije traže vaš pristanak"}}, {"strong": {"en": "Every booking lands in one calendar:", "sr": "Svaka rezervacija stiže u jedan kalendar:"}, "text": {"en": "with the customer's details and history attached", "sr": "sa podacima i istorijom klijenta"}}], "msgs": [{"who": "guest", "text": {"en": "Any openings for a cut and beard trim tomorrow after 5?", "sr": "Ima li termina za šišanje i bradu sutra posle 17h?"}}, {"who": "bot", "text": {"en": "Marco has 5:30 or 6:15 free tomorrow. Both take 45 minutes — which suits you?", "sr": "Marko sutra ima slobodno u 17:30 ili 18:15. Oba termina traju 45 minuta — koji vam odgovara?"}}, {"who": "guest", "text": {"en": "5:30, please.", "sr": "17:30, molim."}}]}$j$::jsonb),
  ('tenant', 6, 'points', $j${"eyebrow": {"en": "Discovery", "sr": "Otkrivanje"}, "title": {"en": "New customers find you in the app", "sr": "Novi klijenti vas pronalaze u aplikaciji"}, "points": [{"strong": {"en": "Found when it matters:", "sr": "Pronađeni kada je važno:"}, "text": {"en": "when people nearby search for your service, our AI shows you with open time slots", "sr": "kada ljudi u blizini traže vašu uslugu, naš AI prikazuje vas sa slobodnim terminima"}}, {"strong": {"en": "Reviews build your ranking:", "sr": "Recenzije grade vaš rang:"}, "text": {"en": "good reviews mean priority placement when customers search", "sr": "dobre recenzije znače prioritet kada klijenti pretražuju"}}, {"strong": {"en": "No ads to buy:", "sr": "Bez plaćenih oglasa:"}, "text": {"en": "discovery comes with your listing — nothing extra to run", "sr": "otkrivanje dolazi uz vaš profil — ništa dodatno ne vodite"}}], "kicker": {"en": "Let new customers find you easily", "sr": "Neka vas novi klijenti lako pronađu"}}$j$::jsonb),
  ('tenant', 7, 'points', $j${"eyebrow": {"en": "Booking Link", "sr": "Link za rezervacije"}, "title": {"en": "One link that books you everywhere", "sr": "Jedan link koji vas zakazuje svuda"}, "points": [{"strong": {"en": "Put it where customers already are:", "sr": "Stavite ga gde su klijenti već:"}, "text": {"en": "Instagram bio, Google profile, WhatsApp replies", "sr": "Instagram bio, Google profil, WhatsApp odgovori"}}, {"strong": {"en": "A booking page built for you:", "sr": "Stranica za rezervacije napravljena za vas:"}, "text": {"en": "services, prices and live availability — customers book without the app", "sr": "usluge, cene i dostupnost uživo — klijenti rezervišu i bez aplikacije"}}, {"strong": {"en": "Every booking lands in one calendar:", "sr": "Svaka rezervacija stiže u jedan kalendar:"}, "text": {"en": "with the customer's details attached", "sr": "sa podacima klijenta"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 8, 'points', $j${"eyebrow": {"en": "Regular Customers", "sr": "Stalni klijenti"}, "title": {"en": "Regulars come back before they drift", "sr": "Stalni klijenti se vraćaju pre nego što se izgube"}, "points": [{"strong": {"en": "Balkina learns their rhythm:", "sr": "Balkina uči njihov ritam:"}, "text": {"en": "every four weeks, every summer — the AI knows when a regular is due", "sr": "svake četiri nedelje, svakog leta — AI zna kada je stalnom klijentu vreme"}}, {"strong": {"en": "A nudge at the right moment:", "sr": "Podsticaj u pravom trenutku:"}, "text": {"en": "a friendly push notification with a one-tap rebook", "sr": "prijateljska notifikacija sa ponovnim zakazivanjem jednim dodirom"}}, {"strong": {"en": "You do nothing:", "sr": "Vi ne radite ništa:"}, "text": {"en": "it runs in the background for every customer", "sr": "radi u pozadini za svakog klijenta"}}], "kicker": {"en": "Let your loyal customers come back often", "sr": "Neka se verni klijenti često vraćaju"}}$j$::jsonb),
  ('tenant', 9, 'points', $j${"eyebrow": {"en": "Reminders", "sr": "Podsetnici"}, "title": {"en": "Fewer no-shows, without the phone calls", "sr": "Manje nedolazaka, bez telefonskih poziva"}, "points": [{"strong": {"en": "Automatic reminders:", "sr": "Automatski podsetnici:"}, "text": {"en": "AI and SMS reminders before every appointment", "sr": "AI i SMS podsetnici pre svakog termina"}}, {"strong": {"en": "Confirm or reschedule in one tap:", "sr": "Potvrda ili pomeranje jednim dodirom:"}, "text": {"en": "customers fix their own plans — your calendar stays accurate", "sr": "klijenti sami sređuju svoje planove — vaš kalendar ostaje tačan"}}, {"strong": {"en": "Your rules:", "sr": "Vaša pravila:"}, "text": {"en": "choose when reminders go out and what they say", "sr": "izaberite kada podsetnici idu i šta piše u njima"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 10, 'points', $j${"eyebrow": {"en": "Customer CRM", "sr": "CRM klijenata"}, "title": {"en": "Remember every customer", "sr": "Zapamtite svakog klijenta"}, "points": [{"strong": {"en": "One profile per customer:", "sr": "Jedan profil po klijentu:"}, "text": {"en": "history, preferences, notes and no-shows", "sr": "istorija, navike, beleške i nedolasci"}}, {"strong": {"en": "Context before they walk in:", "sr": "Kontekst pre nego što uđu:"}, "text": {"en": "see what they had last time and who did it", "sr": "vidite šta su imali prošli put i ko je radio"}}, {"strong": {"en": "Reach them directly:", "sr": "Kontaktirajte ih direktno:"}, "text": {"en": "call, text, WhatsApp or email from the profile", "sr": "poziv, poruka, WhatsApp ili mejl iz profila"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 11, 'points', $j${"eyebrow": {"en": "Set Up Your Business", "sr": "Podesite svoj biznis"}, "title": {"en": "Services, staff and schedules — set once", "sr": "Usluge, osoblje i rasporedi — podesite jednom"}, "points": [{"strong": {"en": "Services the way you sell them:", "sr": "Usluge onako kako ih prodajete:"}, "text": {"en": "durations, prices, buffer times, add-ons", "sr": "trajanja, cene, pauze, dodaci"}}, {"strong": {"en": "Staff and their hours:", "sr": "Osoblje i njihovo radno vreme:"}, "text": {"en": "per-person availability, days off, who does what", "sr": "dostupnost po osobi, slobodni dani, ko šta radi"}}, {"strong": {"en": "One location or many:", "sr": "Jedna lokacija ili više njih:"}, "text": {"en": "each with its own hours and team", "sr": "svaka sa svojim radnim vremenom i timom"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 12, 'points', $j${"eyebrow": {"en": "Appointments", "sr": "Termini"}, "title": {"en": "Manage every appointment end to end", "sr": "Vodite svaki termin od početka do kraja"}, "points": [{"strong": {"en": "Approve or auto-confirm:", "sr": "Odobrite ili automatski potvrdite:"}, "text": {"en": "you decide which bookings need a yes from you", "sr": "vi odlučujete koje rezervacije traže vaš pristanak"}}, {"strong": {"en": "Reschedule in seconds:", "sr": "Pomerite za par sekundi:"}, "text": {"en": "drag to a new slot — the customer is notified", "sr": "prevucite na novi termin — klijent dobija obaveštenje"}}, {"strong": {"en": "On your phone or desktop:", "sr": "Na telefonu ili računaru:"}, "text": {"en": "the same calendar behind the counter and on the go", "sr": "isti kalendar iza pulta i u pokretu"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 13, 'points', $j${"eyebrow": {"en": "Coupons & Packages", "sr": "Kuponi i paketi"}, "title": {"en": "Entice new customers, upsell regulars", "sr": "Privucite nove klijente, prodajte više stalnima"}, "points": [{"strong": {"en": "Coupons:", "sr": "Kuponi:"}, "text": {"en": "discount codes with limits and expiry, redeemed at booking", "sr": "kodovi za popust sa ograničenjima i rokom, iskorišćeni pri rezervaciji"}}, {"strong": {"en": "Package deals:", "sr": "Paketi:"}, "text": {"en": "bundle services or sessions at a better price", "sr": "spojite usluge ili sesije po boljoj ceni"}}, {"strong": {"en": "Tracked automatically:", "sr": "Praćeno automatski:"}, "text": {"en": "usage and revenue per offer, in your dashboard", "sr": "korišćenje i prihod po ponudi, u vašoj tabli"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 14, 'points', $j${"eyebrow": {"en": "Calendar Sync", "sr": "Sinhronizacija kalendara"}, "title": {"en": "Keep all your existing calendars in sync", "sr": "Držite sve postojeće kalendare usklađene"}, "points": [{"strong": {"en": "Google Calendar, two-way:", "sr": "Google kalendar, dvosmerno:"}, "text": {"en": "Balkina bookings appear in Google; your busy times block Balkina automatically", "sr": "Balkina rezervacije se pojavljuju u Google-u; vaši zauzeti termini automatski blokiraju Balkinu"}}, {"strong": {"en": "iCal everywhere:", "sr": "iCal svuda:"}, "text": {"en": "export to Apple Calendar and Outlook; import Airbnb, Calendly and others", "sr": "izvezite u Apple Calendar i Outlook; uvezite Airbnb, Calendly i druge"}}, {"strong": {"en": "Double-booking-proof:", "sr": "Bez duplih rezervacija:"}, "text": {"en": "a busy slot anywhere is a busy slot everywhere", "sr": "zauzet termin bilo gde je zauzet svuda"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 15, 'points', $j${"eyebrow": {"en": "Travel Platforms", "sr": "Turističke platforme"}, "title": {"en": "Sell on Viator and GetYourGuide — bookings flow straight in", "sr": "Prodajete na Viator-u i GetYourGuide-u — rezervacije stižu same"}, "points": [{"strong": {"en": "Connect Bokun once:", "sr": "Povežite Bokun jednom:"}, "text": {"en": "your Viator, GetYourGuide and Airbnb Experiences bookings appear in Balkina", "sr": "vaše rezervacije s Viator-a, GetYourGuide-a i Airbnb Experiences-a se pojavljuju u Balkini"}}, {"strong": {"en": "One capacity, everywhere:", "sr": "Jedan kapacitet, svuda:"}, "text": {"en": "no overselling a tour that's already full", "sr": "bez preprodaje ture koja je već puna"}}, {"strong": {"en": "Direct bookings too:", "sr": "I direktne rezervacije:"}, "text": {"en": "locals and repeat guests book you commission-free", "sr": "lokalni i stalni gosti vas rezervišu bez provizije"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 16, 'points', $j${"eyebrow": {"en": "Hospitality", "sr": "Ugostiteljstvo"}, "title": {"en": "Balkina AI books tables and ticketed evenings, too", "sr": "Balkina AI rezerviše i stolove i večeri s ulaznicama"}, "points": [{"strong": {"en": "Table reservations:", "sr": "Rezervacije stolova:"}, "text": {"en": "party size, your open hours, and your confirmation — you stay in control of the floor", "sr": "broj gostiju, vaše radno vreme i vaša potvrda — vi držite salu pod kontrolom"}}, {"strong": {"en": "Ticketed experiences:", "sr": "Doživljaji s ulaznicama:"}, "text": {"en": "brunches, tastings, holiday dinners with per-person pricing, capacity, and RSVPs", "sr": "branč, degustacije i praznične večere sa cenom po osobi, kapacitetom i prijavama"}}, {"strong": {"en": "The same one dashboard:", "sr": "Ista jedna tabla:"}, "text": {"en": "runs it all, from a single table for two to a sold-out New Year's Eve", "sr": "vodi sve — od stola za dvoje do rasprodatog dočeka Nove godine"}}], "kicker": {"en": "", "sr": ""}}$j$::jsonb),
  ('tenant', 17, 'divider', $j${"title": {"en": "Get Started", "sr": "Počnite"}, "lede": {"en": "Free to try. Live in an afternoon", "sr": "Besplatno za probu. Aktivno za jedno popodne"}, "mock": "booking"}$j$::jsonb),
  ('tenant', 18, 'points', $j${"eyebrow": {"en": "Easy Setup", "sr": "Lako podešavanje"}, "title": {"en": "Free to start. Live in an afternoon", "sr": "Besplatno za početak. Aktivno za jedno popodne"}, "points": [{"strong": {"en": "Create your account:", "sr": "Napravite nalog:"}, "text": {"en": "sign up free in minutes, no credit card required", "sr": "registrujte se besplatno za par minuta, bez kreditne kartice"}}, {"strong": {"en": "Add your services and staff:", "sr": "Dodajte usluge i osoblje:"}, "text": {"en": "set durations, prices and working hours — Balkina builds your booking page", "sr": "podesite trajanja, cene i radno vreme — Balkina pravi vašu stranicu za rezervacije"}}, {"strong": {"en": "Share your link and go live:", "sr": "Podelite svoj link i krenite:"}, "text": {"en": "your first booking can arrive the same day", "sr": "prva rezervacija može stići istog dana"}}], "kicker": {"en": "No hardware and nothing to install", "sr": "Bez opreme i bez instalacija"}}$j$::jsonb),
  ('tenant', 19, 'pricing', $j${"eyebrow": {"en": "Pricing", "sr": "Cene"}, "title": {"en": "Start free. Grow when you do", "sr": "Počnite besplatno. Rastite svojim tempom"}, "kicker": {"en": "7-day free trial on every plan — no credit card, cancel anytime", "sr": "7 dana besplatne probe uz svaki plan — bez kartice, otkažite bilo kad"}, "plans": [{"name": "Solo", "price": "€5", "per": {"en": "/mo", "sr": "/mes"}, "aud": {"en": "For individuals getting started", "sr": "Za pojedince na početku"}, "line": {"en": "1 staff · 1 location · 20 bookings/mo", "sr": "1 zaposleni · 1 lokacija · 20 rezervacija/mes"}, "popular": false, "badge": {"en": "", "sr": ""}}, {"name": "Solo Pro", "price": "€19", "per": {"en": "/mo", "sr": "/mes"}, "aud": {"en": "For serious solo professionals", "sr": "Za ozbiljne solo profesionalce"}, "line": {"en": "1 staff · 1 location · Unlimited bookings", "sr": "1 zaposleni · 1 lokacija · Neograničene rezervacije"}, "popular": false, "badge": {"en": "", "sr": ""}}, {"name": "Team", "price": "€49", "per": {"en": "/mo", "sr": "/mes"}, "aud": {"en": "For small teams", "sr": "Za male timove"}, "line": {"en": "Up to 5 staff · 2 locations · +€6/additional staff", "sr": "Do 5 zaposlenih · 2 lokacije · +6 €/dodatni zaposleni"}, "popular": true, "badge": {"en": "Most Popular", "sr": "Najpopularniji"}}, {"name": "Scale", "price": "€99", "per": {"en": "/mo", "sr": "/mes"}, "aud": {"en": "For growing businesses", "sr": "Za rastuće biznise"}, "line": {"en": "Up to 15 staff · 5 locations · +€6/additional staff", "sr": "Do 15 zaposlenih · 5 lokacija · +6 €/dodatni zaposleni"}, "popular": false, "badge": {"en": "", "sr": ""}}]}$j$::jsonb),
  ('tenant', 20, 'cta', $j${"eyebrow": {"en": "Get Started", "sr": "Počnite"}, "title_pre": {"en": "Put your bookings on", "sr": "Prebacite rezervacije na"}, "title_em": {"en": "autopilot", "sr": "autopilot"}, "lede": {"en": "Create your account, add your services and staff, and share your link — you can take your first booking today", "sr": "Napravite nalog, dodajte usluge i osoblje i podelite svoj link — prvu rezervaciju možete primiti već danas"}, "btn_label": {"en": "Start your free trial", "sr": "Započnite besplatnu probu"}, "btn_url": "https://balkina.ai/join", "dlnote": {"en": "Download our app to see how your customers will experience it", "sr": "Preuzmite našu aplikaciju i pogledajte kako će je vaši klijenti doživeti"}}$j$::jsonb);
